const trend = $input.json;

if (!trend.title) {
  throw new Error('Invalid trend data: missing title');
}

return {
  title: trend.title,
  description: trend.description || '',
  source: trend.source || 'unknown',
  url: trend.url,
  keywords: extractKeywords(trend.title),
  timestamp: new Date().toISOString()
};

function extractKeywords(text) {
  return text.split(' ')
    .filter(word => word.length > 3)
    .slice(0, 5);
}

