const response = $input.json;

if (!response.choices || response.choices.length === 0) {
  throw new Error('No script generated from OpenAI');
}

const scriptContent = response.choices[0].message.content;

return {
  script: scriptContent,
  title: generateTitle("{{ $node['Process - Validate Trend Data'].json.title }}"),
  description: generateDescription("{{ $node['Process - Validate Trend Data'].json.title }}"),
  keywords: "{{ $node['Process - Validate Trend Data'].json.keywords.join(', ') }}",
  duration_estimate: Math.floor(scriptContent.split(' ').length / 3),
  status: 'generated',
  timestamp: new Date().toISOString()
};

function generateTitle(trend) {
  return `Why Everyone's Talking About ${trend} | Trending Now`;
}

function generateDescription(trend) {
  return `Discover why ${trend} is trending right now. In this video, we break down the latest developments. Don't miss out on this viral topic!`;
}

